mapper.select:
SELECT p.id, p.category_id, p.product_name, p.sub_title, p.main_image, p.status, CASE p.status WHEN 0 THEN '下架' WHEN 1 THEN '上架' WHEN 2 THEN '草稿' ELSE '未知' END AS status_text, COUNT(s.id) AS sku_count, IFNULL(SUM(s.stock), 0) AS stock_total, IFNULL(SUM(s.sales), 0) AS sales, p.created_at FROM product p LEFT JOIN product_sku s ON s.product_id = p.id AND s.deleted = 0 WHERE p.deleted = 0
AND p.category_id = #{categoryId}
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.sub_title LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
AND p.created_at >= #{startTime}
AND p.created_at <= #{endTime}
GROUP BY p.id, p.category_id, p.product_name, p.sub_title, p.main_image, p.status, p.created_at ORDER BY p.created_at DESC
